// EPUB 3 exporter using epub-gen-memory, as validated with epubcheck 5.3.0:
// title page outside the index and before the TOC, TOC generated by the
// library with a tocTitle in the book language, chapters in order. EPUB is the format
// recommended for KDP ebooks.

import epubGenModule from 'epub-gen-memory';
import epub3PackageTemplate from 'epub-gen-memory/dist/lib/templates/epub3/content.opf.ejs';

import { composeChapters, escapeHtml, exportLabels, exportLanguage } from './compose';
import type { BookForExport, Exporter } from './types';

// Default export interop (operational note): depending on the module context
// the default may arrive nested.
const epubGen: typeof epubGenModule =
  (epubGenModule as unknown as { default?: typeof epubGenModule }).default ?? epubGenModule;

// The library always writes <dc:description>, even when empty, and EPUBCheck
// rejects an empty element (RSC-005). KDP takes the description from its own
// form, not from the file, so a blank one is simply left out. Only that line of
// the library's own package template changes; if a library upgrade changes it,
// fail loudly here instead of shipping an invalid EPUB.
const DESCRIPTION_LINE = '<dc:description><%= description %></dc:description>';
if (!epub3PackageTemplate.includes(DESCRIPTION_LINE)) {
  throw new Error('epub-gen-memory package template changed: review the description handling');
}
const PACKAGE_TEMPLATE = epub3PackageTemplate.replace(
  DESCRIPTION_LINE,
  `<% if (description) { %>${DESCRIPTION_LINE}<% } %>`,
);

function titlePageHtml(book: BookForExport): string {
  const genre = book.genre.trim();
  const author = book.author.trim();
  return [
    '<div style="text-align:center; margin-top:30%;">',
    `  <h1 style="font-size:2em;">${escapeHtml(book.title)}</h1>`,
    genre === '' ? '' : `  <p style="font-style:italic;">${escapeHtml(genre)}</p>`,
    author === '' ? '' : `  <p style="margin-top:3em;">${escapeHtml(author)}</p>`,
    '</div>',
  ]
    .filter((line) => line !== '')
    .join('\n');
}

export class EpubExporter implements Exporter {
  readonly format = 'epub' as const;
  readonly mimeType = 'application/epub+zip';
  readonly extension = 'epub';

  async render(book: BookForExport, generatedAt: Date): Promise<Buffer> {
    const chapters = [
      {
        title: book.title,
        content: titlePageHtml(book),
        excludeFromToc: true,
        beforeToc: true,
      },
      ...composeChapters(book).map((chapter) => ({
        title: chapter.displayTitle,
        content: chapter.paragraphs
          .map((paragraph) => `<p>${escapeHtml(paragraph)}</p>`)
          .join('\n'),
      })),
    ];

    const author = book.author.trim();
    const result = await epubGen(
      {
        title: book.title,
        ...(author === '' ? {} : { author }),
        lang: exportLanguage(book.language),
        description: book.description.trim(),
        contentOPF: PACKAGE_TEMPLATE,
        tocTitle: exportLabels(book.language).contents,
        prependChapterTitles: true,
        date: generatedAt.toISOString(),
      },
      chapters,
    );

    // In Node epub-gen-memory returns a Buffer; the guard covers the Blob
    // variant of the browser build (same defense).
    return Buffer.isBuffer(result)
      ? result
      : Buffer.from(await (result as unknown as Blob).arrayBuffer());
  }
}
